package music

import (
	"fmt"
	"math"
	"strconv"
)

// A synthetic test track (development and tests only, never a product sound): a four-on-the-floor kick at bpm with hi-hats on the
// off-beats, a quiet intro (hats, a soft kick and a pad) and a drop on the beat nearest dropS where a full kick and a bass come in. It is
// generated by ffmpeg's aevalsrc, so it needs no asset and no licence, and its beats and drop are known exactly.

// SyntheticDropMs is the drop of the synthetic track: the beat nearest dropS.
func SyntheticDropMs(bpm, dropS float64) int64 {
	period := 60 / bpm
	return int64(math.Round(math.Round(dropS/period) * period * 1000))
}

// SyntheticTrackArgs are the ffmpeg arguments (without the program name) that write the synthetic track of durS seconds to out as 48 kHz
// stereo (the container from out's extension).
func SyntheticTrackArgs(bpm, dropS, durS float64, out string) []string {
	t := strconv.FormatFloat(60/bpm, 'f', 6, 64)
	drop := strconv.FormatFloat(float64(SyntheticDropMs(bpm, dropS))/1000, 'f', 6, 64)
	// p: time since the beat; q: time since the off-beat; d: 1 from the drop on.
	p := fmt.Sprintf("mod(t,%s)", t)
	q := fmt.Sprintf("mod(t+%s/2,%s)", t, t)
	d := fmt.Sprintf("gte(t,%s)", drop)
	kick := fmt.Sprintf("sin(2*PI*(48*%s+2.6*(1-exp(-%s*30))))*exp(-%s*9)", p, p, p)
	hat := fmt.Sprintf("sin(2*PI*7919*t)*sin(2*PI*5737*t)*exp(-%s*70)", q)
	bass := fmt.Sprintf("sin(2*PI*55*t)*(1-exp(-%s*20))*exp(-%s*2)", p, p)
	pad := "(sin(2*PI*220*t)+sin(2*PI*277.2*t)+sin(2*PI*329.6*t))/3"
	expr := fmt.Sprintf("(1-%s)*(0.12*%s+0.06*%s+0.12*%s)+%s*(0.8*%s+0.22*%s+0.3*%s+0.05*%s)", d, kick, hat, pad, d, kick, hat, bass, pad)
	src := fmt.Sprintf("aevalsrc=exprs='%s|%s':s=48000:d=%s", expr, expr, strconv.FormatFloat(durS, 'f', 3, 64))
	return []string{"-hide_banner", "-loglevel", "error", "-y", "-f", "lavfi", "-i", src, "-ac", "2", out}
}
